-- Comentarios da Lei 15.040/2024, lote 2 (arts. 21 a 40). Autorizados pela Jessica em 22/10/2026; so a partir do texto no banco.
-- Reverter: update legislacao set contexto=null, aplicacao_pratica=null where codigo='lei15040' and numero between 21 and 40 and paragrafo is null and inciso is null;
update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(21,'Resolução do contrato por inadimplemento do prêmio','A resolução do contrato, salvo quando se tratar de mora da prestação única ou da primeira parcela do prêmio, está condicionada a notificação prévia e não poderá ocorrer em prazo inferior a 30 (trinta) dias após a suspensão da garantia. O § 1º dispõe que a resolução libera integralmente a seguradora por sinistros e despesas de salvamento ocorridos a partir de então. O § 2º dispõe que, nos seguros coletivos sobre a vida e a integridade física, a resolução somente ocorrerá 90 (noventa) dias após a última notificação feita ao estipulante. O § 3º trata dos seguros sobre a vida e a integridade física estruturados com reserva matemática: o não pagamento de parcela do prêmio que não a primeira implica a redução proporcional da garantia ou a devolução da reserva, conforme a escolha do segurado ou de seus beneficiários, a ser feita dentro de 30 (trinta) dias contados da notificação do inadimplemento, nos termos do parágrafo. O § 4º dispõe que o prazo do caput terá início na data da frustração da notificação sempre que o segurado ou o estipulante recusar o recebimento ou, por qualquer razão, não for encontrado no último endereço informado à seguradora ou no que constar dos cadastros normalmente utilizados pelas instituições financeiras. O § 5º dispensa a notificação do caput quando a notificação de suspensão da garantia, de que tratam os §§ 1º, 2º e 3º do art. 20, advertir para a resolução do contrato caso não purgada a mora.'),
(22,'Prêmio nos seguros de vida e integridade física','Nos seguros sobre a vida e a integridade física, o prêmio pode ser convencionado por prazo limitado ou por toda a vida do segurado.'),
(23,'Execução para cobrança do prêmio','Caberá execução para a cobrança do prêmio, se infrutífera a notificação realizada pela seguradora, e sempre que esta houver suportado o risco que recai sobre o interesse garantido.'),
(24,'Seguro em favor de terceiro','O seguro será estipulado em favor de terceiro quando garantir interesse de titular distinto do estipulante, determinado ou determinável. O § 1º dispõe que o beneficiário será identificado por lei, por ato de vontade anterior à ocorrência do sinistro ou pela titularidade do interesse garantido. O § 2º dispõe que, sendo determinado o beneficiário a título oneroso, a seguradora e o estipulante deverão entregar-lhe, tão logo quanto possível, cópia dos instrumentos probatórios do contrato.'),
(25,'Declaração de interesse alheio e escolha da seguradora e do corretor','O interesse alheio, sempre que conhecido pelo proponente, deve ser declarado à seguradora. O § 1º dispõe que se presume que o seguro é por conta própria, salvo quando, em razão das circunstâncias ou dos termos do contrato, a seguradora tiver ciência de que o seguro é em favor de terceiro. O § 2º dispõe que, na contratação do seguro em favor de terceiro, ainda que decorrente de cumprimento de dever, não poderá ser suprimida a escolha da seguradora e do corretor de seguro por parte do estipulante.'),
(26,'Coexistência de seguro em favor de terceiro e por conta própria','O seguro em favor de terceiro pode coexistir com o seguro por conta própria, ainda que no âmbito do mesmo contrato. O parágrafo único dispõe que, salvo disposição em contrário, se houver concorrência de interesses garantidos, prevalecerá a garantia por conta própria, sendo considerada, naquilo que ultrapassar o valor do interesse próprio, como em favor de terceiro, sempre respeitado o limite da garantia.'),
(27,'Obrigações do estipulante','O estipulante deverá cumprir as obrigações e os deveres do contrato, salvo os que por sua natureza devam ser cumpridos pelo segurado ou pelo beneficiário.'),
(28,'Substituição processual pelo estipulante','O estipulante poderá substituir processualmente o segurado ou o beneficiário para exigir, em favor exclusivo destes, o cumprimento das obrigações derivadas do contrato.'),
(29,'Assistência do estipulante ao segurado e ao beneficiário','Cabe ao estipulante, além de outras atribuições que decorram de lei ou de convenção, assistir o segurado ou o beneficiário durante a execução do contrato.'),
(30,'Estipulante de seguro coletivo','Considera-se estipulante de seguro coletivo aquele que contrata em proveito de um grupo de pessoas, pactuando com a seguradora os termos do contrato para a adesão de eventuais interessados.'),
(31,'Vínculo prévio do estipulante e responsabilidade pelo prêmio','Admite-se como estipulante de seguro coletivo apenas aquele que tiver vínculo anterior e não securitário com o grupo de pessoas em proveito do qual contratar o seguro, sem o que o seguro será considerado individual. O § 1º dispõe que as quantias eventualmente pagas ao estipulante de seguro coletivo pelos serviços prestados deverão ser informadas com destaque aos segurados ou aos beneficiários nas propostas de adesão, nos questionários e nos demais documentos do contrato. O § 2º dispõe que, salvo disposição em contrário, o estipulante de seguro coletivo sobre a vida e a integridade física do segurado é o único responsável perante a seguradora pelo cumprimento de todas as obrigações contratuais, inclusive a de pagar o prêmio.'),
(32,'Representação dos segurados pelo estipulante','O estipulante de seguro coletivo representa os segurados e os beneficiários durante a formação e a execução do contrato e responde perante eles e a seguradora por seus atos e omissões. O parágrafo único dispõe que, para que possam valer as exceções e as defesas da seguradora em razão das declarações prestadas para a formação do contrato, o documento de adesão ao seguro deverá ter seu conteúdo preenchido pessoalmente pelos segurados ou pelos beneficiários.'),
(33,'Cosseguro','Ocorre cosseguro quando 2 (duas) ou mais seguradoras, por acordo expresso entre si e o segurado ou o estipulante, garantem o mesmo interesse contra o mesmo risco, ao mesmo tempo, cada uma delas assumindo uma cota de garantia.'),
(34,'Documentação do cosseguro','O cosseguro poderá ser documentado em 1 (um) ou mais instrumentos contratuais emitidos por cada uma das cosseguradoras com o mesmo conteúdo. O § 1º dispõe que o documento probatório do contrato deverá destacar a existência do cosseguro, as seguradoras participantes e a cota da garantia assumida por cada uma. O § 2º dispõe que, se não houver inequívoca identificação da cosseguradora líder, os interessados devem dirigir-se àquela que emitiu o documento probatório ou a cada uma das emitentes, se o contrato for documentado em diversos instrumentos.'),
(35,'Cosseguradora líder','A cosseguradora líder administra o cosseguro, representando as demais na formação e na execução do contrato, e as substitui, ativa ou passivamente, nas arbitragens e nos processos judiciais. O § 1º dispõe que, quando a ação for proposta apenas contra a líder, esta deverá, no prazo de sua resposta, comunicar a existência do cosseguro e promover a notificação judicial ou extrajudicial das cosseguradoras. O § 2º dispõe que a sentença proferida contra a líder fará coisa julgada em relação às demais, que serão executadas nos mesmos autos. O § 3º dispõe que não há solidariedade entre as cosseguradoras, arcando cada uma exclusivamente com sua cota de garantia, salvo previsão contratual diversa. O § 4º dispõe que o descumprimento de obrigações entre as cosseguradoras não prejudicará o segurado, o beneficiário ou o terceiro.'),
(36,'Seguro cumulativo','Ocorre seguro cumulativo quando a distribuição entre várias seguradoras for feita pelo segurado ou pelo estipulante por força de contratações independentes, sem limitação a uma cota de garantia. O § 1º dispõe que, nos seguros cumulativos de dano, o segurado deverá comunicar a cada uma das seguradoras a existência dos contratos com as demais. O § 2º dispõe que será reduzida proporcionalmente a importância segurada de cada contrato celebrado, quando a soma das importâncias seguradas, nos seguros cumulativos de dano, superar o valor do interesse, desde que haja coincidência de garantia entre os seguros cumulados. O § 3º dispõe que, na redução proporcional do § 2º, não se levarão em conta os contratos celebrados com seguradoras que se encontrarem insolventes.'),
(37,'Lealdade, boa-fé e informação dos intervenientes','Os intervenientes são obrigados a agir com lealdade e boa-fé e prestar informações completas e verídicas sobre todas as questões envolvendo a formação e a execução do contrato.'),
(38,'Vinculação da seguradora por representantes e prepostos','Os representantes e os prepostos da seguradora, ainda que temporários ou a título precário, vinculam-na para todos os fins quanto a seus atos e omissões.'),
(39,'Entrega de documentos pelo corretor de seguro','O corretor de seguro é responsável pela efetiva entrega ao destinatário dos documentos e outros dados que lhe forem confiados, no prazo máximo de 5 (cinco) dias úteis. O parágrafo único dispõe que, sempre que for conhecido o iminente perecimento de direito, a entrega deve ser feita em prazo hábil.'),
(40,'Comissão de corretagem e renovação por outro corretor','Pelo exercício de sua atividade, o corretor de seguro fará jus à comissão de corretagem. O parágrafo único dispõe que a renovação ou a prorrogação do seguro, quando não automática ou se implicar alteração de conteúdo de cobertura ou financeiro mais favorável aos segurados e aos beneficiários, poderá ser intermediada por outro corretor de seguro, de livre escolha do segurado ou do estipulante.')
) as v(n,c,a)
where l.codigo='lei15040' and l.numero=v.n and l.paragrafo is null and l.inciso is null and l.vigente;
